"""Install the approved Clinify Prescription Print Format.

This patch is intentionally idempotent and provisions the exact
Stage 6-B approved Clinify Prescription Print Format.
"""

import frappe

PRINT_FORMAT_NAME = "Clinify Prescription"
PRINT_HTML = '\n<style>\n@page {\n    size: A4;\n    margin: 8mm;\n}\n\n* {\n    box-sizing: border-box;\n}\n\nbody {\n    margin: 0;\n    padding: 0;\n    background: #ffffff;\n    color: #111111;\n    font-family: Arial, Helvetica, sans-serif;\n    font-size: 10px;\n}\n\n.clinify-page {\n    width: 100%;\n    min-height: 275mm;\n    border: 1.5px solid #173b82;\n    border-radius: 5px;\n    padding: 18px;\n    background: #ffffff;\n}\n\n/* =========================================================\n   HEADER\n   ========================================================= */\n\n.clinify-header {\n    width: 100%;\n    min-height: 118px;\n    border: 2px solid #173b82;\n    border-radius: 4px 4px 0 0;\n    padding: 14px 16px;\n    display: table;\n    table-layout: fixed;\n}\n\n.header-left,\n.header-center,\n.header-right {\n    display: table-cell;\n    vertical-align: middle;\n}\n\n.header-left {\n    width: 18%;\n    text-align: center;\n    border-right: 2px solid #173b82;\n    padding-right: 12px;\n}\n\n.header-center {\n    width: 52%;\n    padding-left: 20px;\n}\n\n.header-right {\n    width: 30%;\n    text-align: right;\n    padding-left: 10px;\n}\n\n.clinify-logo {\n    max-width: 92px;\n    max-height: 82px;\n    object-fit: contain;\n}\n\n.clinify-name {\n    color: #173b82;\n    font-size: 30px;\n    font-weight: 700;\n    letter-spacing: 1px;\n    line-height: 1;\n}\n\n.clinify-tagline {\n    margin-top: 5px;\n    font-size: 14px;\n    color: #222222;\n}\n\n.clinic-detail {\n    margin-top: 10px;\n    font-size: 11px;\n    line-height: 1.55;\n    color: #222222;\n}\n\n.doctor-name {\n    color: #173b82;\n    font-size: 21px;\n    font-weight: 700;\n}\n\n.doctor-qualification {\n    margin-top: 8px;\n    color: #173b82;\n    font-size: 14px;\n    font-weight: 700;\n}\n\n.doctor-designation {\n    margin-top: 8px;\n    font-size: 13px;\n    color: #222222;\n}\n\n/* =========================================================\n   PATIENT INFORMATION\n   ========================================================= */\n\n.patient-title {\n    margin: 18px 0 10px 0;\n    text-align: center;\n    color: #173b82;\n    font-size: 15px;\n    font-weight: 700;\n    letter-spacing: .3px;\n}\n\n.patient-title:before,\n.patient-title:after {\n    display: none;\n}\n\n.patient-card {\n    width: 100%;\n    border: 1px solid #cccccc;\n    border-radius: 4px;\n    padding: 6px 8px;\n    display: table;\n    table-layout: fixed;\n}\n\n.patient-item {\n    display: table-cell;\n    width: 20%;\n    vertical-align: middle;\n    padding: 1px 8px;\n    border-right: 1px solid #cccccc;\n}\n\n.patient-item:last-child {\n    border-right: none;\n}\n\n.patient-icon {\n    display: table-cell;\n    width: 38px;\n    vertical-align: middle;\n    color: #173b82;\n    text-align: center;\n}\n\n.patient-icon svg {\n    width: 24px;\n    height: 24px;\n    display: inline-block;\n    vertical-align: middle;\n    fill: #173b82;\n    stroke: #173b82;\n}\n\n.patient-data {\n    display: table-cell;\n    vertical-align: middle;\n    padding-left: 7px;\n}\n\n.patient-label {\n    display: block;\n    font-size: 8px;\n    color: #555555;\n    margin-bottom: 2px;\n}\n\n.patient-value {\n    display: block;\n    font-size: 12px;\n    font-weight: 400;\n    color: #111111;\n}\n\n/* =========================================================\n   SECTION HEADINGS\n   ========================================================= */\n\n.section-title {\n    margin-top: 18px;\n    margin-bottom: 8px;\n    font-size: 15px;\n    font-weight: 700;\n    color: #111111;\n}\n\n/* =========================================================\n   CHIEF COMPLAINT / NOTE\n   ========================================================= */\n\n.text-box {\n    width: 100%;\n    min-height: 62px;\n    border: 1px solid #888888;\n    padding: 10px;\n    font-size: 12px;\n    font-weight: 400;\n    line-height: 1.5;\n}\n\n/* =========================================================\n   TABLES\n   ========================================================= */\n\n.prescription-table {\n    width: 100%;\n    border-collapse: collapse;\n    table-layout: fixed;\n    font-size: 10.5px;\n}\n\n.prescription-table th {\n    background: #f1f1f1;\n    border: 1px solid #b9b9b9;\n    padding: 9px 10px;\n    text-align: left;\n    font-weight: 700;\n    color: #333333;\n}\n\n.prescription-table td {\n    border: 1px solid #b9b9b9;\n    padding: 10px;\n    height: 34px;\n    font-weight: 400;\n    color: #111111;\n    vertical-align: middle;\n}\n\n.center {\n    text-align: center !important;\n}\n\n/* =========================================================\n   SIGNATURE\n   ========================================================= */\n\n.signature-area {\n    margin-top: 42px;\n    width: 260px;\n    margin-left: auto;\n    text-align: center;\n}\n\n.signature-line {\n    border-top: 1px solid #222222;\n    padding-top: 7px;\n    font-size: 11px;\n}\n\n/* =========================================================\n   PRINT SAFETY\n   ========================================================= */\n\ntable,\ntr,\ntd,\nth {\n    page-break-inside: avoid;\n}\n\n.clinify-section {\n    page-break-inside: avoid;\n}\n\n\n.lab-table {\n    width: 100%;\n    border-collapse: collapse;\n    table-layout: fixed;\n    margin-top: 6px;\n    margin-bottom: 12px;\n}\n\n.lab-table th,\n.lab-table td {\n    border: 1px solid #888;\n    padding: 6px 7px;\n    vertical-align: top;\n    line-height: 1.35;\n}\n\n.lab-table th {\n    font-weight: 700;\n    background: #f5f5f5;\n}\n\n.lab-name-col {\n    width: 55%;\n}\n\n.lab-comment-col {\n    width: 45%;\n}\n\n\n\n.clinical-notes-content {\n    border: 1px solid #888;\n    border-radius: 3px;\n    min-height: 50px;\n    padding: 8px 10px;\n    margin-top: 6px;\n    margin-bottom: 12px;\n    line-height: 1.4;\n}\n\n\n\n/* =========================================================\n   DOCTOR NOTES — FULL WIDTH CLINICAL SECTION\n   ========================================================= */\n\n.doctor-notes-section {\n    width: 100%;\n    display: block;\n    clear: both;\n    margin-top: 18px;\n    margin-bottom: 16px;\n    text-align: left !important;\n    page-break-inside: avoid;\n}\n\n.doctor-notes-section .section-title {\n    width: 100%;\n    margin-top: 0;\n    margin-bottom: 7px;\n    text-align: left !important;\n}\n\n.doctor-notes-content {\n    width: 100%;\n    display: block;\n    margin: 0;\n    padding: 0;\n    border: none !important;\n    border-radius: 0 !important;\n    text-align: left !important;\n    font-size: 12px;\n    line-height: 1.5;\n    color: #111111;\n}\n\n.doctor-notes-content * {\n    text-align: left !important;\n}\n\n\n\n.lab-table th {\n    color: #111111 !important;\n}\n\n\n/* =========================================================\n   CLINIFY VITALS — COMPACT 32% PRESCRIPTION HEADER\n   ========================================================= */\n\n.clinical-visit-table {\n    width: 100%;\n    border-collapse: collapse;\n    table-layout: fixed;\n    margin-top: 18px;\n    margin-bottom: 0;\n    page-break-inside: avoid;\n}\n\n.clinical-visit-table > tbody > tr > td {\n    vertical-align: top;\n    padding: 0;\n}\n\n.clinical-complaint-cell {\n    width: 68%;\n    padding-right: 8px !important;\n}\n\n.clinical-vitals-cell {\n    width: 32%;\n    padding-left: 6px !important;\n}\n\n.clinical-vitals-cell .section-title,\n.clinical-complaint-cell .section-title {\n    margin-top: 0;\n}\n\n/* Compact Vitals container. */\n.clinical-vitals-box {\n    width: 100%;\n    box-sizing: border-box;\n    border: 1px solid #888888;\n    padding: 3px 4px;\n    border-radius: 3px;\n    font-size: 8.5px;\n    line-height: 1.0;\n    overflow: hidden;\n}\n\n/* Three compact columns. */\n.clinical-vitals-grid {\n    width: 100%;\n    border-collapse: collapse;\n    table-layout: fixed;\n}\n\n.clinical-vitals-grid td {\n    padding: 2px 2px;\n    vertical-align: middle;\n    white-space: nowrap;\n    line-height: 1.0;\n    font-size: 8.5px;\n}\n\n/* Each vital occupies one compact grid cell. */\n.clinical-vitals-grid .vital-item {\n    width: 33.333%;\n    box-sizing: border-box;\n    padding: 2px 2px;\n    text-align: left;\n}\n\n/* Thin separator between columns. */\n.clinical-vitals-grid .vital-item + .vital-item {\n    border-left: 1px solid #e2e2e2;\n    padding-left: 4px;\n}\n\n/* Complete the 3-column × 2-row Vitals grid.\n   This adds only the internal horizontal divider and\n   does not alter the overall Vitals box dimensions. */\n.clinical-vitals-grid tbody tr + tr td {\n    border-top: 1px solid #e2e2e2;\n}\n\n/* Backend-style compact icon. */\n.clinical-vitals-grid .vital-icon {\n    display: inline-block;\n    width: 10px;\n    min-width: 10px;\n    height: 10px;\n    margin-right: 2px;\n    vertical-align: -1px;\n    text-align: center;\n    font-size: 8px;\n    font-weight: 700;\n    line-height: 10px;\n}\n\n/* Icon colours follow the Vital Signs UI visual language. */\n.clinical-vitals-grid .bp-icon {\n    color: #3b82f6;\n}\n\n.clinical-vitals-grid .pulse-icon {\n    color: #ec4899;\n}\n\n.clinical-vitals-grid .temp-icon {\n    color: #f97316;\n}\n\n.clinical-vitals-grid .resp-icon {\n    color: #3b82f6;\n}\n\n.clinical-vitals-grid .weight-icon {\n    color: #8b5cf6;\n}\n\n.clinical-vitals-grid .bmi-icon {\n    color: #22c55e;\n}\n\n.clinical-vitals-grid .height-icon {\n    color: #3b82f6;\n}\n\n.clinical-vitals-grid .vital-label {\n    font-weight: 600;\n}\n\n.clinical-vitals-grid .vital-value {\n    font-weight: 400;\n}\n\n/* Optional Height row. */\n.clinical-vitals-grid .height-item {\n    width: 100%;\n    padding-top: 2px;\n    border-top: 1px solid #e2e2e2;\n}\n\n</style>\n\n<div class="clinify-page">\n\n    {# =====================================================\n       HEADER\n       ===================================================== #}\n\n    {% set clinic = frappe.get_doc("Clinic Configuration", "Clinic Configuration") %}\n\n    {% if doc.practitioner %}\n        {% set practitioner = frappe.get_doc(\n            "Healthcare Practitioner",\n            doc.practitioner\n        ) %}\n    {% endif %}\n\n    <div class="clinify-header">\n\n        <div class="header-left">\n            <img\n                class="clinify-logo"\n                src="/assets/clinify/images/clinify-logo.png"\n            >\n        </div>\n\n        <div class="header-center">\n\n            <div class="clinify-name">\n                {{ clinic.clinic_name or "CLINIFY" }}\n            </div>\n\n            <div class="clinify-tagline">\n                Healthcare, Simplified\n            </div>\n\n            <div class="clinic-detail">\n\n                {% if clinic.clinic_address or clinic.city or clinic.state or clinic.pincode %}\n                    📍\n                    {{ clinic.clinic_address or "" }}\n                    {% if clinic.city %}, {{ clinic.city }}{% endif %}\n                    {% if clinic.state %}, {{ clinic.state }}{% endif %}\n                    {% if clinic.pincode %} - {{ clinic.pincode }}{% endif %}\n                    <br>\n                {% endif %}\n\n                {% if clinic.clinic_phone %}\n                    ☎\n                    Phone: {{ clinic.clinic_phone }}\n                {% endif %}\n\n                {% if clinic.clinic_email %}\n                    {% if clinic.clinic_phone %} &nbsp; | &nbsp; {% endif %}\n                    Email: {{ clinic.clinic_email }}\n                {% endif %}\n\n            </div>\n\n        </div>\n\n        <div class="header-right">\n\n            {% if practitioner %}\n                <div class="doctor-name">\n                    Dr. {{ practitioner.practitioner_name or "" }}\n                </div>\n\n                {% if practitioner.qualifications %}\n                    <div class="doctor-qualification">\n                        {{ practitioner.qualifications }}\n                    </div>\n                {% endif %}\n\n                {% if practitioner.designation %}\n                    <div class="doctor-designation">\n                        {{ frappe.db.get_value(\n                            "Designation",\n                            practitioner.designation,\n                            "designation_name"\n                        ) or practitioner.designation }}\n                    </div>\n                {% endif %}\n            {% endif %}\n\n        </div>\n\n    </div>\n\n    {# =====================================================\n       PATIENT INFORMATION\n       ORDER:\n       NAME | ID | AGE | GENDER | DATE\n       ===================================================== #}\n    {% if doc.patient %}\n        {% set patient_doc = frappe.get_doc("Patient", doc.patient) %}\n    {% endif %}\n\n    <div class="patient-card">\n\n        <div class="patient-item">\n            \n<div class="patient-icon">\n    <svg viewBox="0 0 48 48" aria-hidden="true">\n        <circle cx="24" cy="24" r="21"\n                fill="none"\n                stroke="#173b82"\n                stroke-width="3"/>\n        <circle cx="24" cy="17" r="7"/>\n        <path d="M11 39c1-8 6-12 13-12s12 4 13 12z"/>\n    </svg>\n</div>\n\n            <div class="patient-data">\n                <span class="patient-label">Patient Name</span>\n                <span class="patient-value">\n                    {{ doc.patient_name or (patient_doc.patient_name if patient_doc else "-") }}\n                </span>\n            </div>\n        </div>\n\n        <div class="patient-item">\n            \n<div class="patient-icon">\n    <svg viewBox="0 0 48 48" aria-hidden="true">\n        <rect x="9" y="7" width="30" height="34"\n              rx="3"\n              fill="none"\n              stroke="#173b82"\n              stroke-width="3"/>\n        <circle cx="24" cy="17" r="6"/>\n        <path d="M14 32c1-6 5-9 10-9s9 3 10 9z"/>\n        <path d="M18 37h12"\n              fill="none"\n              stroke="#173b82"\n              stroke-width="2"/>\n    </svg>\n</div>\n\n            <div class="patient-data">\n                <span class="patient-label">Patient ID</span>\n                <span class="patient-value">\n                    {{ patient_doc.uid or "-" if patient_doc else "-" }}\n                </span>\n            </div>\n        </div>\n\n        <div class="patient-item">\n            \n<div class="patient-icon">\n    <svg viewBox="0 0 48 48" aria-hidden="true">\n        <circle cx="24" cy="14" r="7"/>\n        <path d="M10 40c1-10 6-16 14-16s13 6 14 16z"/>\n    </svg>\n</div>\n\n            <div class="patient-data">\n                <span class="patient-label">Age</span>\n                <span class="patient-value">\n                    {{ doc.patient_age or "-" }}\n                </span>\n            </div>\n        </div>\n\n        <div class="patient-item">\n            \n<div class="patient-icon">\n    <svg viewBox="0 0 48 48" aria-hidden="true">\n        <circle cx="20" cy="28" r="10"\n                fill="none"\n                stroke="#173b82"\n                stroke-width="4"/>\n        <path d="M27 21L39 9"\n              fill="none"\n              stroke="#173b82"\n              stroke-width="4"/>\n        <path d="M30 9h9v9"\n              fill="none"\n              stroke="#173b82"\n              stroke-width="4"/>\n    </svg>\n</div>\n\n            <div class="patient-data">\n                <span class="patient-label">Gender</span>\n                <span class="patient-value">\n                    {{ doc.patient_sex or "-" }}\n                </span>\n            </div>\n        </div>\n\n        <div class="patient-item">\n            \n<div class="patient-icon">\n    <svg viewBox="0 0 48 48" aria-hidden="true">\n        <rect x="7" y="10" width="34" height="31"\n              rx="3"\n              fill="none"\n              stroke="#173b82"\n              stroke-width="3"/>\n        <path d="M7 19h34"\n              fill="none"\n              stroke="#173b82"\n              stroke-width="3"/>\n        <path d="M15 6v8M33 6v8"\n              fill="none"\n              stroke="#173b82"\n              stroke-width="4"/>\n        <circle cx="16" cy="26" r="2"/>\n        <circle cx="24" cy="26" r="2"/>\n        <circle cx="32" cy="26" r="2"/>\n        <circle cx="16" cy="33" r="2"/>\n        <circle cx="24" cy="33" r="2"/>\n        <circle cx="32" cy="33" r="2"/>\n    </svg>\n</div>\n\n            <div class="patient-data">\n                <span class="patient-label">Date</span>\n                <span class="patient-value">\n                    {{ frappe.format_date(doc.encounter_date) if doc.encounter_date else "-" }}\n                </span>\n            </div>\n        </div>\n\n    </div>\n\n    {# =====================================================\n       CLINICAL VISIT SUMMARY + VITALS\n       ===================================================== #}\n\n    {# Match vitals using the same visit rules as Clinify:\n       1. Same Patient Appointment\n       2. Same Patient + Encounter Date\n       No historical encounter-only fallback is used.\n    #}\n\n    {% set print_vitals = [] %}\n\n{% if doc.appointment and doc.patient %}\n    {% set print_vitals = frappe.get_all(\n        "Vital Signs",\n        filters={\n            "appointment": doc.appointment,\n            "patient": doc.patient\n        },\n        fields=[\n            "name",\n            "signs_date",\n            "signs_time",\n            "temperature",\n            "pulse",\n            "respiratory_rate",\n            "bp_systolic",\n            "bp_diastolic",\n            "weight",\n            "bmi",\n            "height"\n        ],\n        order_by="signs_date desc, signs_time desc, creation desc",\n        limit_page_length=1\n    ) %}\n{% endif %}\n\n{% if not print_vitals and doc.patient and doc.encounter_date %}\n    {% set print_vitals = frappe.get_all(\n        "Vital Signs",\n        filters={\n            "patient": doc.patient,\n            "signs_date": doc.encounter_date\n        },\n        fields=[\n            "name",\n            "signs_date",\n            "signs_time",\n            "temperature",\n            "pulse",\n            "respiratory_rate",\n            "bp_systolic",\n            "bp_diastolic",\n            "weight",\n            "bmi",\n            "height"\n        ],\n        order_by="signs_time desc, creation desc",\n        limit_page_length=1\n    ) %}\n{% endif %}\n\n\n<table class="clinical-visit-table">\n    <tbody>\n        <tr>\n\n            <!--\n                HISTORICAL CLINIFY ARCHITECTURE:\n                Chief Complaint is always rendered.\n                The Vitals cell alone is conditional.\n            -->\n\n            <td class="clinical-complaint-cell">\n                <div class="section-title">Chief Complaint</div>\n                <div class="text-box">\n                    {% if doc.encounter_comment %}\n                        {{ doc.encounter_comment }}\n                    {% elif doc.custom_chief_complaint %}\n                        {{ doc.custom_chief_complaint }}\n                    {% else %}\n                        <span class="empty-note">No chief complaint recorded.</span>\n                    {% endif %}\n                </div>\n            </td>\n\n            {% if print_vitals %}\n                {% set vital = print_vitals[0] %}\n\n                <td class="clinical-vitals-cell">\n                    <div class="section-title">Vitals</div>\n\n                    <div class="clinical-vitals-box">\n                        <table class="clinical-vitals-grid">\n                            <tbody>\n\n                                <tr>\n\n                                    <td class="vital-item">\n                                        {% if vital.bp_systolic or vital.bp_diastolic %}\n                                            <span class="vital-icon bp-icon">◆</span>\n                                            <span class="vital-label">BP</span>\n                                            <span class="vital-value">\n                                                {{ vital.bp_systolic or "-" }}/{{ vital.bp_diastolic or "-" }}\n                                            </span>\n                                        {% endif %}\n                                    </td>\n\n                                    <td class="vital-item">\n                                        {% if vital.pulse %}\n                                            <span class="vital-icon pulse-icon">♥</span>\n                                            <span class="vital-label">Pulse</span>\n                                            <span class="vital-value">\n                                                {{ vital.pulse }}\n                                            </span>\n                                        {% endif %}\n                                    </td>\n\n                                    <td class="vital-item">\n                                        {% if vital.temperature %}\n                                            <span class="vital-icon temp-icon">♨</span>\n                                            <span class="vital-label">Temp</span>\n                                            <span class="vital-value">\n                                                {{ vital.temperature }}\n                                            </span>\n                                        {% endif %}\n                                    </td>\n\n                                </tr>\n\n                                <tr>\n\n                                    <td class="vital-item">\n                                        {% if vital.respiratory_rate %}\n                                            <span class="vital-icon resp-icon">♥</span>\n                                            <span class="vital-label">Resp</span>\n                                            <span class="vital-value">\n                                                {{ vital.respiratory_rate }}\n                                            </span>\n                                        {% endif %}\n                                    </td>\n\n                                    <td class="vital-item">\n                                        {% if vital.weight and vital.weight != 0 %}\n                                            <span class="vital-icon weight-icon">⚖</span>\n                                            <span class="vital-label">Wt</span>\n                                            <span class="vital-value">\n                                                {{ vital.weight }} kg\n                                            </span>\n                                        {% endif %}\n                                    </td>\n\n                                    <td class="vital-item">\n                                        {% if vital.bmi and vital.bmi != 0 %}\n                                            <span class="vital-icon bmi-icon">↗</span>\n                                            <span class="vital-label">BMI</span>\n                                            <span class="vital-value">\n                                                {{ vital.bmi }}\n                                            </span>\n                                        {% endif %}\n                                    </td>\n\n                                </tr>\n\n                                {% if vital.height and vital.height != 0 %}\n                                <tr>\n                                    <td colspan="3" class="vital-item height-item">\n                                        <span class="vital-icon height-icon">↕</span>\n                                        <span class="vital-label">Height</span>\n                                        <span class="vital-value">\n                                            {{ vital.height }} cm\n                                        </span>\n                                    </td>\n                                </tr>\n                                {% endif %}\n\n                            </tbody>\n                        </table>\n                    </div>\n                </td>\n            {% endif %}\n\n        </tr>\n    </tbody>\n</table>\n\n{% if doc.custom_dental_services %}\n<div class="section-title">\n    DENTAL SERVICES\n</div>\n\n<table class="prescription-table">\n    <thead>\n        <tr>\n            <th style="width:45%;">Dental Service</th>\n            <th style="width:20%;">Tooth / Area</th>\n            <th style="width:10%;">Quantity</th>\n            <th style="width:25%;">Remarks</th>\n        </tr>\n    </thead>\n    <tbody>\n        {% for row in doc.custom_dental_services %}\n        <tr>\n            <td>\n                {{\n                    frappe.db.get_value(\n                        "Dental Service",\n                        row.dental_service,\n                        "service_name"\n                    )\n                    or row.dental_service\n                    or ""\n                }}\n            </td>\n            <td>{{ row.tooth_area or "" }}</td>\n            <td>{{ row.qty or 1 }}</td>\n            <td>{{ row.remarks or "" }}</td>\n        </tr>\n        {% endfor %}\n    </tbody>\n</table>\n{% endif %}\n\n\n{% if doc.lab_test_prescription %}\n<div class="section-title">\n    LAB TESTS\n</div>\n\n<table class="lab-table">\n    <thead>\n        <tr>\n            <th class="lab-name-col">Lab Test</th>\n            <th class="lab-comment-col">Comments</th>\n        </tr>\n    </thead>\n    <tbody>\n        {% for row in doc.lab_test_prescription %}\n        <tr>\n            <td>\n                {{ row.lab_test_name or row.lab_test_code or "" }}\n            </td>\n            <td>\n                {{ row.lab_test_comment or "" }}\n            </td>\n        </tr>\n        {% endfor %}\n    </tbody>\n</table>\n{% endif %}\n\n\n{% if doc.drug_prescription %}\n<div class="section-title">\n    PRESCRIPTION\n</div>\n\n<table class="prescription-table">\n    <thead>\n        <tr>\n            <th class="medicine-col">Medicine / Description</th>\n            <th class="dosage-col">Strength</th>\n            <th class="dosage-col">Dosage</th>\n            <th class="period-col">Period</th>\n            <th class="instruction-col">Instruction</th>\n        </tr>\n    </thead>\n    <tbody>\n        {% for row in doc.drug_prescription %}\n        <tr>\n            <td>\n                {{ row.drug_name or row.drug_code or "" }}\n            </td>\n            <td>\n                {{ row.dosage_form or "" }}\n            </td>\n            <td>\n                {{ row.dosage or "" }}\n            </td>\n            <td>\n                {{ row.period or "" }}\n            </td>\n            <td>\n                {{ row.custom_instruction or "" }}\n            </td>\n        </tr>\n        {% endfor %}\n    </tbody>\n</table>\n{% endif %}\n\n\n\n    {# =====================================================\n       SIGNATURE\n       ===================================================== #}\n\n    \n{% if doc.custom_doctor_notes and frappe.utils.strip_html(doc.custom_doctor_notes).strip() %}\n\n<div class="doctor-notes-section">\n\n    <div class="section-title">\n        Doctor\'s Notes / Advice\n    </div>\n\n    <div class="doctor-notes-content">\n        {{ doc.custom_doctor_notes }}\n    </div>\n\n</div>\n\n{% endif %}\n\n<div class="signature-area">\n\n    <div class="signature-line">\n        Doctor Signature\n    </div>\n\n</div>\n\n\n</div>\n'

EXPECTED_SHA256 = "94fd72c512f6eef0d077649ac4580306a06d54e5b66426931d8362cf7b76c33c"


def execute():
    import hashlib

    actual_sha256 = hashlib.sha256(
        PRINT_HTML.encode("utf-8")
    ).hexdigest()

    if actual_sha256 != EXPECTED_SHA256:
        frappe.throw(
            "Clinify Prescription HTML integrity check failed."
        )

    if frappe.db.exists("Print Format", PRINT_FORMAT_NAME):
        doc = frappe.get_doc("Print Format", PRINT_FORMAT_NAME)
    else:
        doc = frappe.new_doc("Print Format")
        doc.name = PRINT_FORMAT_NAME

    doc.doc_type = "Patient Encounter"
    doc.print_format_type = "Jinja"
    doc.disabled = 0
    doc.standard = "No"
    doc.custom_format = 1
    doc.module = "Clinify"
    doc.html = PRINT_HTML

    doc.save(ignore_permissions=True)
    frappe.db.commit()

    return {
        "name": PRINT_FORMAT_NAME,
        "sha256": actual_sha256,
        "bytes": len(PRINT_HTML.encode("utf-8")),
    }
